function mathQuestion(rng: () => number, kinds?: number[]): TQ {
  const kind = (kinds && kinds.length) ? kinds[Math.floor(rng() * kinds.length)] : Math.floor(rng() * 7);
  let a = 0, b = 0, ans = 0, expr = "";
  if (kind === 0) { a = 2 + Math.floor(rng() * 98); b = 2 + Math.floor(rng() * 98); ans = a + b; expr = a + " + " + b; }
  else if (kind === 1) { a = 10 + Math.floor(rng() * 90); b = 1 + Math.floor(rng() * a); ans = a - b; expr = a + " − " + b; }
  else if (kind === 2) { a = 2 + Math.floor(rng() * 11); b = 2 + Math.floor(rng() * 11); ans = a * b; expr = a + " × " + b; }
  else if (kind === 3) { b = 2 + Math.floor(rng() * 11); ans = 2 + Math.floor(rng() * 11); a = b * ans; expr = a + " ÷ " + b; }
  else if (kind === 4) { a = 2 + Math.floor(rng() * 20); ans = a * a; expr = a + "²"; }
  else if (kind === 5) { a = 2 + Math.floor(rng() * 9); b = 2 + Math.floor(rng() * 9); const c0 = 2 + Math.floor(rng() * 9); ans = a + b * c0; expr = a + " + " + b + " × " + c0; }
  else { a = 2 + Math.floor(rng() * 9); b = 2 + Math.floor(rng() * 9); const c0 = 2 + Math.floor(rng() * 9); ans = (a + b) * c0; expr = "(" + a + " + " + b + ") × " + c0; }
  const set = new Set<number>([ans]);
  let guard = 0;
  while (set.size < 4 && guard < 50) { guard++; const delta = (Math.floor(rng() * 9) - 4) + (rng() < 0.3 ? (Math.floor(rng() * 7) - 3) * 2 : 0); const d = ans + delta; if (d !== ans && d >= 0) set.add(d); }
  while (set.size < 4) { set.add(ans + set.size + 1); }
  const opts = Array.from(set);
  for (let i = opts.length - 1; i > 0; i--) { const j = Math.floor(rng() * (i + 1)); const t = opts[i]; opts[i] = opts[j]; opts[j] = t; }
  const c = opts.indexOf(ans);
  const q: any = {};
  (["en", "ar", "uk", "fr", "de"] as TLang[]).forEach((l) => { q[l] = MATH_PREFIX[l] + " " + expr + "?"; });
  return { q, o: opts.map(String), c };
}

export function genMaths(count: number): TQ[] {
  const rng = mulberry32(777);
  const out: TQ[] = []; const seen = new Set<string>();
  let guard = 0;
  while (out.length < count && guard < count * 30) { guard++; const q = mathQuestion(rng); if (seen.has(q.q.en)) continue; seen.add(q.q.en); out.push(q); }
  return out;
}

export function genMathsRandom(count: number, level?: string): TQ[] {
  const rng = Math.random;
  const kinds = level === "easy" ? [0, 1] : level === "intermediate" ? [2, 3] : level === "hard" ? [4, 5, 6] : undefined;
  const out: TQ[] = []; const seen = new Set<string>();
  let guard = 0;
  while (out.length < count && guard < count * 40) { guard++; const q = mathQuestion(rng, kinds); if (seen.has(q.q.en)) continue; seen.add(q.q.en); out.push(q); }
  return out;
}

const BANK_CACHE: Record<string, TQ[]> = {};
export function getBank(categoryId: string): TQ[] {
  if (BANK_CACHE[categoryId]) return BANK_CACHE[categoryId];
  let bank: TQ[] = categoryId === "maths" ? genMaths(500) : ((TRIVIA_DATA.curated as any)[categoryId] || []);
  if (categoryId !== "maths") {
    const LV = ["easy", "intermediate", "hard"];
    bank = bank.map((q) => (q.d ? q : { ...q, d: LV[hashStr(q.q.en) % 3] }));
  }
  BANK_CACHE[categoryId] = bank;
  return bank;
}
export function bankSize(categoryId: string): number { return getBank(categoryId).length; }

function optsFor(q: TQ, lang: TLang): string[] {
  if (lang === "ar" && q.oar) return q.oar;
  if (lang === "uk" && q.ouk) return q.ouk;
  return q.o;
}

export interface PlayQuestion { id: string; text: string; options: string[]; correctAnswer: number; type: "multiple"; timeLimit: number; points: number; }

export function toPlayQuestion(q: TQ, lang: TLang, idx: number): PlayQuestion {
  const base = optsFor(q, lang);
  const correctVal = base[q.c];
  const opts = base.slice();
  for (let i = opts.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); const tmp = opts[i]; opts[i] = opts[j]; opts[j] = tmp; }
  const ci = opts.indexOf(correctVal);
  return { id: "tq" + idx, text: q.q[lang] || q.q.en, options: opts, correctAnswer: ci >= 0 ? ci : 0, type: "multiple", timeLimit: 15, points: 1000 };
}

const USED_KEY = (c: string) => "quizups:triviaUsed:" + c;
function readUsed(cat: string): number[] { try { const r = window.localStorage.getItem(USED_KEY(cat)); const a = r ? JSON.parse(r) : []; return Array.isArray(a) ? a : []; } catch (e) { return []; } }
function writeUsed(cat: string, idxs: number[]) { try { window.localStorage.setItem(USED_KEY(cat), JSON.stringify(idxs.slice(-400))); } catch (e) {} }

export function pickQuestions(categoryId: string, n: number, lang: TLang, level?: string): PlayQuestion[] {
  if (categoryId === "maths") {
    const fresh = genMathsRandom(n, level);
    return fresh.map((q, k) => toPlayQuestion(q, lang, Date.now() + k));
  }
  const bank = getBank(categoryId);
  if (!bank.length) return [];
  let allIdx = bank.map((_, i) => i);
  if (level) { const tagged = allIdx.filter((i) => (bank[i] as any).d === level); if (tagged.length >= n) allIdx = tagged; }
  const used = new Set(readUsed(categoryId + ":" + (level || "mix")));
  let pool = allIdx.filter((i) => !used.has(i));
  if (pool.length < n) { writeUsed(categoryId + ":" + (level || "mix"), []); pool = allIdx.slice(); }
  for (let i = pool.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); const tmp = pool[i]; pool[i] = pool[j]; pool[j] = tmp; }
  const chosen = pool.slice(0, Math.min(n, pool.length));
  writeUsed(categoryId + ":" + (level || "mix"), readUsed(categoryId + ":" + (level || "mix")).concat(chosen));
  return chosen.map((i, k) => toPlayQuestion(bank[i], lang, i * 1000 + k));
}

export interface Competitor { name: string; score: number; fake: true; }
export function seededCompetitors(categoryId: string, count = 20): Competitor[] {
  const names: string[] = TRIVIA_DATA.names;
  const day = Math.floor(Date.now() / 86400000);
  const rng = mulberry32((hashStr(categoryId) ^ day) >>> 0);
  const picks: Competitor[] = [];
  const usedNames = new Set<number>();
  let guard = 0;
  while (picks.length < count && guard < count * 20) {
    guard++;
    const ni = Math.floor(rng() * names.length);
    if (usedNames.has(ni)) continue;
    usedNames.add(ni);
    const score = 1200 + Math.floor(rng() * 7000);
    picks.push({ name: names[ni], score, fake: true });
  }
  return picks.sort((a, b) => b.score - a.score);
}
